query:
SELECT ?item ?code ?rank ?end ?dissolved ?ru WHERE {
  ?item p:P300 ?statement .
  ?statement ps:P300 ?code ;
             wikibase:rank ?rank .
  OPTIONAL { ?statement pq:P582 ?end . }
  OPTIONAL { ?item wdt:P576 ?dissolved . }
  OPTIONAL { ?item rdfs:label ?ru . FILTER(LANG(?ru) = "ru") }
}
